import{_ as n,c as t,b as s,o as a}from"./app-DRXmfGxI.js";const o={};function l(p,e){return a(),t("div",null,e[0]||(e[0]=[s(`<p>In today&#39;s fast-paced e-commerce landscape, staying ahead of the curve is essential for success.</p><p>That&#39;s why our E-Signature Feature app in the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace App</a> for Shopify is a game-changer for your online business.</p><p>Unlock the potential of e-signatures, empowering you to streamline transactions, foster trust among customers, and elevate the overall shopping experience.</p><h3 id="introduction" tabindex="-1"><a class="header-anchor" href="#introduction"><span>Introduction</span></a></h3><p>Using our E-Signature Feature app in the <a href="https://apps.shopify.com/multi-vendor-marketplace" target="_blank" rel="noopener noreferrer">Multivendor Marketplace App for Shopify, admins,</a> and sellers can effortlessly create E-Signature documents.</p><p>These documents can be connected to seller products, allowing customers to sign them before adding items to their cart, streamlining the shopping experience.</p><p><strong>CHARGES</strong></p><p>The E-Signature feature app will have an additional charge of <strong>USD 20 per month</strong> over &amp; above your current Multivendor Marketplace app plan.</p><h3 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h3><p>Enable the E-Signature feature app by following the below steps:</p><ul><li>Go to Multivendor <strong>Admin Panel</strong></li><li>From the Dashboard, hover over the <strong>three dots</strong> on the top-right of the page</li><li>Click on <strong>Feature Apps</strong></li><li>Search for <strong>‘E-Signature‘</strong> &amp; click on ‘<strong>Enable</strong>‘</li><li>After accepting the charges, you’ll be good to configure the app.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698238037016-1200x619.png" alt="screenshot_1698238037016"></p><h3 id="need-to-add-code-to-allow-customers-to-e-sign-on-pdf-on-the-product-page" tabindex="-1"><a class="header-anchor" href="#need-to-add-code-to-allow-customers-to-e-sign-on-pdf-on-the-product-page"><span>Need to add code to allow customers to e-sign on pdf on the product page</span></a></h3><p>Copy the following code and add it into <strong>product.json &gt;&gt; sections/main-product.liquid</strong> template</p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%</span> <span class="token keyword">if</span> <span class="token object">product</span><span class="token punctuation">.</span>tags <span class="token operator">contains</span> <span class="token string">&#39;wk_esign_document&#39;</span> <span class="token delimiter punctuation">%}</span></span>  </span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>wk_esignate_document_active <span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-productid</span> <span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>  </span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> <span class="token object">product</span><span class="token punctuation">.</span>id <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-variantid</span> <span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>  </span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> <span class="token object">product</span><span class="token punctuation">.</span>selected_or_first_available_variant<span class="token punctuation">.</span>id <span class="token delimiter punctuation">}}</span></span> </span>
<span class="line">    <span class="token punctuation">&quot;</span></span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none<span class="token punctuation">;</span> </span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%</span> <span class="token keyword">render</span> <span class="token string">&quot;wk-esignature-document&quot;</span> <span class="token delimiter punctuation">%}</span></span></span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%-</span> <span class="token keyword">endif</span> <span class="token delimiter punctuation">-%}</span></span>       </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698411765895-2-1200x521.jpeg" alt="screenshot_1698411765895-2"></p><p>Copy the below code and add it into <strong>templates &gt;&gt; customer/order.liquid</strong> template</p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%</span> <span class="token keyword">if</span> property<span class="token punctuation">.</span><span class="token function">first</span> <span class="token operator">==</span> <span class="token string">&#39;wk-esgin-document-id&#39;</span><span class="token delimiter punctuation">%}</span></span>  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>wk-esign-product-  <span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> <span class="token object">product</span><span class="token punctuation">.</span>id <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">&quot;</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%-</span> <span class="token keyword">endif</span> <span class="token delimiter punctuation">-%}</span></span>                      </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698411841444-2-1200x524.jpeg" alt="screenshot_1698411841444-2"></p><p>Select and copy the below-given code and add it into <strong>Checkout Settings&gt;&gt; Additional scripts</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>  <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>section wk-cus-esign-document<span class="token punctuation">&quot;</span></span> <span class="token attr-name">&quot;</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>                  </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698411874068-1200x530.jpeg" alt="screenshot_1698411874068"></p><p>Add class to your quantity selector. Copy the code and add it into <strong>product.json &gt;&gt; sections/main-product.liquid</strong> template</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">    wk_qty_selector         </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698411729982-1200x541.jpeg" alt="screenshot_1698411729982"></p><p>Add class to your add to cart button. Copy the code below and add it into <strong>product.json &gt;&gt; sections/buy-buttons.liquid</strong> template</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">    wk_esignature_cart                 </span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698411813711-1200x535.jpeg" alt="screenshot_1698411813711"></p><p><strong>NOTE:</strong> These codes are also accessible in the Multivendor Marketplace Admin Panel under Configuration &gt;&gt; Instructions For Marketplace in the E-Signature Document section.</p><p><strong>If the admin wants to enable sellers to add documents to their products for E-Signature, they can do so by following these steps:</strong></p><ol><li>Go to Multivendor Admin Panel.</li><li>Navigate to Configuration.</li><li>Select Product Configuration from the dropdown options.</li><li>Locate/search for <strong>&quot;ALLOW SELLER TO ADD E-SIGNATURE DOCUMENTS&quot;</strong> and Enable it.</li><li>Save the changes.</li></ol><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698242819211-1200x619.png" alt="screenshot_1698242819211"></p><h3 id="add-document-for-e-signature-admin-end" tabindex="-1"><a class="header-anchor" href="#add-document-for-e-signature-admin-end"><span>Add Document for E-Signature: Admin End</span></a></h3><ul><li>Go to Multi-Vendor <strong>Admin Panel</strong></li><li>Navigate to Products</li><li>Click on E-Signature from the dropdown options.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698238252666-1200x619.png" alt="screenshot_1698238252666"></p><ul><li>On the E-Signature page, you&#39;ll find a &#39;+ Add Document&#39; button on the right-hand side. Click it to upload the document on which you&#39;d like to take e-signatures.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698238327736-1200x619.png" alt="screenshot_1698238327736"></p><p>On the Add E-Signature Page, you&#39;ll find these options:</p><p><strong>1) CHOOSE SELLER</strong></p><ul><li><strong>Choose Specific Seller:</strong> This choice allows you to pick an individual seller for whom you want to create or associate an E-Signature document. To do this, you need to enter the seller&#39;s email address, and the document will be linked to that particular seller.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/ADD-E-SIGNATURE-DOCUMENT-Admin-1197x1024.png" alt="ADD-E-SIGNATURE-DOCUMENT-Admin"></p><ul><li><strong>Choose For All Sellers</strong>: If the admin wants to add an E-Signature document that applies to all the sellers in your marketplace at once, you can select the &quot;Choose All Sellers&quot; option. This means the document will be available for every seller.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/ADD-E-SIGNATURE-DOCUMENT-Admin-1-1200x939.png" alt="ADD-E-SIGNATURE-DOCUMENT-Admin-1"></p><p><strong>2) DOCUMENT NAME</strong>: The admin can name an e-signature document for easy reference.</p><p><strong>3) UPLOAD DOCUMENT</strong>: After the admin has filled in the necessary details and uploaded the document, they&#39;ll promptly receive a popup notification, confirming the successful upload.</p><h3 id="note" tabindex="-1"><a class="header-anchor" href="#note"><span>NOTE:</span></a></h3><p>You can upload a PDF document for e-signature with a maximum of 5 pages, no more.</p><p>After this, a new page labeled &#39;Edit E-Signature Document&#39; will appear. Here, the admin can make three types of edits:</p><ul><li><p>Document Name</p></li><li><p>Custom Fields - We support 6 types of custom fields</p><ol><li>Image Type</li><li>Text Type</li><li>Textarea Type</li><li>Signature Type<br> 5)Date Type</li><li>File Type- In the file type custom field, customers can upload a file of 10 Mb or less.</li></ol></li><li><p>Place Custom Field</p></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/ADD-E-SIGNATURE-DOCUMENT-Admin-2-1200x747.png" alt="ADD-E-SIGNATURE-DOCUMENT-Admin-2"></p><p>Within the Document name section, you can easily edit or update the name of the E-signature document.</p><p>In the Custom Fields section, you have the flexibility to incorporate custom fields into the e-signature document and choose the custom field type that suits your requirements.</p><p><em><strong>NOTE:</strong> You can create a maximum of 40 custom fields for the e-signature document.</em></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698240071342-1200x619.png" alt="screenshot_1698240071342"></p><p>As for the Place Custom Field section, it offers a selection of all the custom fields you&#39;ve added, allowing you to place them in your uploaded document at your preferred location for e-signatures.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698241091950-1200x614.png" alt="screenshot_1698241091950"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/ADD-E-SIGNATURE-DOCUMENT-Admin-3-940x1024.png" alt="ADD-E-SIGNATURE-DOCUMENT-Admin-3"></p><p>You have the flexibility to edit, delete, disable, and change the uploaded document.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698241856955-1200x619.png" alt="screenshot_1698241856955"></p><h3 id="assign-a-document-for-e-signature-in-your-products" tabindex="-1"><a class="header-anchor" href="#assign-a-document-for-e-signature-in-your-products"><span>Assign a document for E-signature in your products</span></a></h3><p>When adding a new product, you&#39;ll conveniently find the option to select an existing e-signature document from a dropdown menu.</p><p>This streamlined process makes it easy to apply the chosen document to the product.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698242360514-1200x618.png" alt="screenshot_1698242360514"></p><p>Admins have the ability to review e-signed documents for any specific order by simply editing that order at any time.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698309173097-1200x531.jpeg" alt="screenshot_1698309173097"></p><h3 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>Seller End</span></a></h3><p>After the admin enables the &#39;ALLOW SELLER TO ADD E-SIGNATURE DOCUMENTS&#39;, sellers gain the ability to include E-signature documents within the Products section.</p><p>This allows sellers to seamlessly integrate E-signature documents into their products according to their specific preferences.</p><p>Sellers can also edit, delete, disable, and change the uploaded document for e-signature.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698243003107-1200x619.jpeg" alt="screenshot_1698243003107"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/ADD-E-SIGNATURE-DOCUMENT-Seller-•-Multivendor-MarketPlace-1200x918.png" alt="ADD-E-SIGNATURE-DOCUMENT-Seller-•-Multivendor-MarketPlace"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698315804974-1200x619.png" alt="screenshot_1698315804974"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698316073116-1200x617.png" alt="screenshot_1698316073116"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698316102812-1200x619.png" alt="screenshot_1698316102812"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698316238744-1200x618.png" alt="screenshot_1698316238744"></p><h3 id="customer-end" tabindex="-1"><a class="header-anchor" href="#customer-end"><span>Customer End</span></a></h3><p>On the Product page, buyers/customers will find a &#39;Sign &amp; Add To Cart&#39; button, as illustrated in the image below:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698302186060-1200x619.png" alt="screenshot_1698302186060"></p><p>When customers click the &quot;Sign &amp; Add To Cart&quot; button, a document will open for them to sign, as depicted in the image below.</p><p>Once they&#39;ve signed it, they can submit the signature and will be provided with the option to &#39;Add to Cart&#39;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698314097454-1200x547.jpeg" alt="screenshot_1698314097454"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698302322193-1200x619.png" alt="screenshot_1698302322193"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698317335743-1200x538.png" alt="screenshot_1698317335743"></p><p>After placing an order on the checkout page, customers have the option to preview and download the E-signature document.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698309283055-1200x553.jpeg" alt="screenshot_1698309283055"></p><p>Also, the customers can log in to their account and preview and download the document from the orders.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/10/screenshot_1698309062337-1200x537.jpeg" alt="screenshot_1698309062337"></p>`,87)]))}const c=n(o,[["render",l]]),r=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Product%20Add-Ons/E-SIGNATURE.html","title":"E-SIGNATURE","lang":"en-US","frontmatter":{"title":"E-SIGNATURE","description":"E-SIGNATURE","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":3,"title":"Installation","slug":"installation","link":"#installation","children":[]},{"level":3,"title":"Need to add code to allow customers to e-sign on pdf on the product page","slug":"need-to-add-code-to-allow-customers-to-e-sign-on-pdf-on-the-product-page","link":"#need-to-add-code-to-allow-customers-to-e-sign-on-pdf-on-the-product-page","children":[]},{"level":3,"title":"Add Document for E-Signature: Admin End","slug":"add-document-for-e-signature-admin-end","link":"#add-document-for-e-signature-admin-end","children":[]},{"level":3,"title":"NOTE:","slug":"note","link":"#note","children":[]},{"level":3,"title":"Assign a document for E-signature in your products","slug":"assign-a-document-for-e-signature-in-your-products","link":"#assign-a-document-for-e-signature-in-your-products","children":[]},{"level":3,"title":"Seller End","slug":"seller-end","link":"#seller-end","children":[]},{"level":3,"title":"Customer End","slug":"customer-end","link":"#customer-end","children":[]}],"git":{},"filePathRelative":"classic/Featured-App/Marketplace Product Add-Ons/E-SIGNATURE.md"}');export{c as comp,r as data};
